        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients
        (
            Action<HttpClient>? client = null, Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = c => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IAdAccountsApi, AdAccountsApi>(client));
            builders.Add(_services.AddHttpClient<IAdGroupsApi, AdGroupsApi>(client));
            builders.Add(_services.AddHttpClient<IAdsApi, AdsApi>(client));
            builders.Add(_services.AddHttpClient<IAdvancedAuctionApi, AdvancedAuctionApi>(client));
            builders.Add(_services.AddHttpClient<IAudienceInsightsApi, AudienceInsightsApi>(client));
            builders.Add(_services.AddHttpClient<IAudienceSharingApi, AudienceSharingApi>(client));
            builders.Add(_services.AddHttpClient<IAudiencesApi, AudiencesApi>(client));
            builders.Add(_services.AddHttpClient<IBillingApi, BillingApi>(client));
            builders.Add(_services.AddHttpClient<IBoardsApi, BoardsApi>(client));
            builders.Add(_services.AddHttpClient<IBulkApi, BulkApi>(client));
            builders.Add(_services.AddHttpClient<IBusinessAccessAssetsApi, BusinessAccessAssetsApi>(client));
            builders.Add(_services.AddHttpClient<IBusinessAccessInviteApi, BusinessAccessInviteApi>(client));
            builders.Add(_services.AddHttpClient<IBusinessAccessRelationshipsApi, BusinessAccessRelationshipsApi>(client));
            builders.Add(_services.AddHttpClient<ICampaignsApi, CampaignsApi>(client));
            builders.Add(_services.AddHttpClient<ICatalogsApi, CatalogsApi>(client));
            builders.Add(_services.AddHttpClient<IConversionEventsApi, ConversionEventsApi>(client));
            builders.Add(_services.AddHttpClient<IConversionTagsApi, ConversionTagsApi>(client));
            builders.Add(_services.AddHttpClient<ICustomerListsApi, CustomerListsApi>(client));
            builders.Add(_services.AddHttpClient<IIntegrationsApi, IntegrationsApi>(client));
            builders.Add(_services.AddHttpClient<IKeywordsApi, KeywordsApi>(client));
            builders.Add(_services.AddHttpClient<ILeadAdsApi, LeadAdsApi>(client));
            builders.Add(_services.AddHttpClient<ILeadFormsApi, LeadFormsApi>(client));
            builders.Add(_services.AddHttpClient<ILeadsExportApi, LeadsExportApi>(client));
            builders.Add(_services.AddHttpClient<IMediaApi, MediaApi>(client));
            builders.Add(_services.AddHttpClient<IOauthApi, OauthApi>(client));
            builders.Add(_services.AddHttpClient<IOrderLinesApi, OrderLinesApi>(client));
            builders.Add(_services.AddHttpClient<IPinsApi, PinsApi>(client));
            builders.Add(_services.AddHttpClient<IProductGroupPromotionsApi, ProductGroupPromotionsApi>(client));
            builders.Add(_services.AddHttpClient<IResourcesApi, ResourcesApi>(client));
            builders.Add(_services.AddHttpClient<ISearchApi, SearchApi>(client));
            builders.Add(_services.AddHttpClient<ITargetingTemplateApi, TargetingTemplateApi>(client));
            builders.Add(_services.AddHttpClient<ITermsApi, TermsApi>(client));
            builders.Add(_services.AddHttpClient<ITermsOfServiceApi, TermsOfServiceApi>(client));
            builders.Add(_services.AddHttpClient<IUserAccountApi, UserAccountApi>(client));
            
            if (builder != null)
                foreach (IHttpClientBuilder instance in builders)
                    builder(instance);

            HttpClientsAdded = true;

            return this;
        }

        /// <summary>
        /// Configures the JsonSerializerSettings
